<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/Upload.php';require_once __DIR__.'/../services/TicketService.php';Auth::requireLogin();$user=Auth::user();if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');$id=TicketService::create($_POST,(int)$user['id']);if(($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$saved=Upload::save($_FILES['attachment'],'uploads/tickets',['pdf','doc','docx','xls','xlsx','jpg','jpeg','png','webp','txt','zip'],10*1024*1024);if(!$saved['ok'])throw new InvalidArgumentException($saved['error']);$message=Database::fetch('SELECT id FROM ticket_messages WHERE ticket_id=? ORDER BY id LIMIT 1',[$id]);TicketService::addAttachment($id,(int)($message['id']??0),(int)$user['id'],$saved);}flash('تیکت با موفقیت ثبت شد.');redirect('/employee/ticket-view.php?id='.$id);}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Ticket create: '.$e->getMessage());flash('ثبت تیکت انجام نشد.','danger');}}$categories=TicketService::categories();$pageTitle='تیکت جدید';require __DIR__.'/../views/partials/admin-header.php';?>
<section class="card admin-form"><div class="section-heading-row"><div><h1>ثبت تیکت جدید</h1><p class="muted">برای پیگیری ساخت‌یافته درخواست؛ پیام‌رسان فقط اعلان می‌فرستد.</p></div><a class="btn" href="/employee/tickets.php">بازگشت</a></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><label class="form-field"><span>عنوان</span><input name="subject" maxlength="255" required></label><div class="grid grid-2"><label class="form-field"><span>دسته‌بندی</span><select name="category_id" required><?php foreach($categories as $category):?><option value="<?=$category['id']?>"><?=e($category['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>اولویت</span><select name="priority"><?php foreach(TicketService::PRIORITIES as $key=>$label):?><option value="<?=$key?>"><?=e($label)?></option><?php endforeach?></select></label></div><label class="form-field"><span>شرح درخواست</span><textarea name="message" rows="8" maxlength="20000" required></textarea></label><label class="form-field"><span>پیوست اختیاری</span><input type="file" name="attachment" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.webp,.txt,.zip"></label><button class="btn btn-primary">ثبت تیکت</button></form></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
